 function textSkills(rows,listeningMode){return {id:listeningMode?'junior_listening':'junior_reading',title:listeningMode?'中学英語・聞いて情報と要点':'中学英語・読解と根拠',stages:[0,1,2,3].map(s=>({title:['具体的な情報','理由と目的','要点と判断','根拠を確かめる'][s],items:rows.slice(s*3,s*3+3).flatMap(([title,text,questions],n)=>questions.map(([prompt,answer,o1,o2,evidence],j)=>({id:`junior-${listeningMode?'listen':'read'}-${s}-${n}-${j}`,mode:listeningMode?'listen':'reading',requiresAudio:listeningMode,fallbackSkillId:'junior_listeningReading',prompt:listeningMode?'会話・案内を聞いて答えよう。\n'+prompt:title+'\n'+text+'\n\n'+prompt,fallbackPrompt:title+'\n'+text+'\n\n'+prompt,audioText:listeningMode?text:'Read the text and choose the answer.',answerAudio:answer,answer,choices:[answer,o1,o2],hint:'本文の手がかり：'+evidence,evidence,passage:text,topic:listeningMode?'listening':'reading'})))}))}}
